/* Wubby’s World — painted pine and birch sprites with actual alpha transparency.
   Two distinct variants per species, extracted from the original transparent art.
   The sprite canvas has no background or terrain tile; roots anchor to game terrain. */
(()=>{'use strict';
const img=new Image();
const api={ready:false,source:'four individually isolated, truly transparent painted trees',draw(ctx,kind,variant,x,y,scale){
 if(!api.ready)return false;
 const family=kind==='birch'?2:0;
 const slot=family+((variant%2+2)%2);
 const width=90*scale*.72,height=130*scale;
 ctx.drawImage(img,slot*90,0,90,130,x-width/2,y-height,width,height);
 return true;
}};
window.WUBBY_PAINTED_FOREST_ART=api;
img.onload=()=>{api.ready=true;window.dispatchEvent(new Event('wubby-painted-forest-ready'))};
img.src='data:image/png;base64,';
})();